'use strict';
(()=>{const button=document.createElement('button');button.className='button secondary compact';button.id='animationOpen';button.textContent='Animasi garis';document.querySelector('.canvas-toolbar').append(button);const d=document.createElement('dialog');d.id='animationDialog';d.innerHTML='<div class="dialog-heading"><h2>Animasi garis</h2><button id="animationClose" class="button secondary">Tutup</button></div><div class="animation-options"><label>Durasi<select id="animationDuration"><option>5</option><option>10</option><option>15</option></select></label><label>Format<select id="animationAspect"><option value="landscape">1920 × 1080</option><option value="portrait">1080 × 1920</option></select></label><label>Gerakan<select id="animationMode"><option value="sequential">Berurutan</option><option value="together">Serentak</option></select></label><label>Urutan<select id="animationOrder"><option value="top">Atas ke bawah</option><option value="left">Kiri ke kanan</option><option value="length">Garis panjang dahulu</option></select></label><label>Lebar garis ×<input id="animationWidth" type="number" min="0.25" max="4" step="0.25" value="1"></label><label>Garis<input type="color" id="animationInk" value="#172d29"></label><label>Latar<input type="color" id="animationBg" value="#ffffff"></label></div><canvas id="animationCanvas"></canvas><div class="animation-actions"><button id="animationPlay" class="button secondary">Play</button><button id="animationReset" class="button secondary">Ulang</button><button id="animationExport" class="button primary">Unduh MP4 · 60 fps</button><button id="animationCancel" class="button secondary" hidden>Batalkan ekspor</button></div><progress id="animationProgress" max="1" value="0"></progress><p id="animationStatus" role="status">Draw-on dari centerline. Hasil lengkap ditahan pada 10% akhir durasi.</p>';document.body.append(d);
let artwork=null,paths=[],total=0,elapsed=0,last=0,raf=0,exporting=false,cancel=false;const canvas=$('animationCanvas'),ctx=canvas.getContext('2d');const duration=()=>+$('animationDuration').value;
function prepare(){const svg=new DOMParser().parseFromString(artwork.svg,'image/svg+xml').documentElement;svg.style.position='absolute';svg.style.visibility='hidden';svg.setAttribute('width',artwork.width);svg.setAttribute('height',artwork.height);d.append(svg);try{paths=[...svg.querySelectorAll('path')].map(p=>{const b=p.getBBox();return {path:new Path2D(p.getAttribute('d')),length:p.getTotalLength(),x:b.x,y:b.y};}).filter(p=>p.length>0);}finally{svg.remove();}const order=$('animationOrder').value;paths.sort((a,b)=>order==='length'?b.length-a.length:order==='left'?a.x-b.x:a.y-b.y);total=paths.reduce((n,p)=>n+p.length,0);}
function draw(time){const portrait=$('animationAspect').value==='portrait',w=portrait?1080:1920,h=portrait?1920:1080;if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}ctx.fillStyle=$('animationBg').value;ctx.fillRect(0,0,w,h);const scale=Math.min(w/artwork.width,h/artwork.height)*.9;ctx.save();ctx.translate((w-artwork.width*scale)/2,(h-artwork.height*scale)/2);ctx.scale(scale,scale);ctx.strokeStyle=$('animationInk').value;ctx.lineWidth=artwork.stroke*Math.max(.25,Math.min(4,Number($('animationWidth').value)||1));ctx.lineCap='round';ctx.lineJoin='round';const fraction=Math.min(1,time/(duration()*.9));let remaining=total*fraction;for(const p of paths){const length=$('animationMode').value==='together'?p.length*fraction:Math.max(0,Math.min(p.length,remaining));remaining-=p.length;if(length<=0)continue;ctx.setLineDash(length>=p.length?[]:[length,p.length+1]);ctx.lineDashOffset=0;ctx.stroke(p.path);}ctx.restore();}
function stop(){cancelAnimationFrame(raf);raf=0;$('animationPlay').textContent='Play';}function tick(now){elapsed=Math.min(duration(),elapsed+(now-last)/1000);last=now;draw(elapsed);if(elapsed<duration())raf=requestAnimationFrame(tick);else stop();}
button.onclick=()=>{if(!result?.td.strokeWidth){showToast('Pilih profil Line Icon lalu proses gambar untuk membuat animasi garis.');return;}artwork={svg:result.svg,width:result.td.width,height:result.td.height,stroke:result.td.strokeWidth,name:source.name.replace(/\.(png|jpe?g)$/i,'')};d.showModal();elapsed=0;refresh();};$('animationPlay').onclick=()=>{if(raf){stop();return;}if(elapsed>=duration())elapsed=0;last=performance.now();$('animationPlay').textContent='Pause';raf=requestAnimationFrame(tick);};$('animationReset').onclick=()=>{stop();elapsed=0;draw(0);};function refresh(){stop();elapsed=0;try{prepare();draw(0);$('animationExport').disabled=false;$('animationPlay').disabled=false;}catch(e){$('animationStatus').textContent=e.message;$('animationExport').disabled=true;$('animationPlay').disabled=true;}}for(const input of d.querySelectorAll('select,input'))input.onchange=refresh;$('animationClose').onclick=()=>{stop();d.close();};d.addEventListener('cancel',e=>{if(exporting)e.preventDefault();else stop();});$('animationCancel').onclick=()=>{cancel=true;};
$('animationExport').onclick=async()=>{if(exporting)return;stop();exporting=true;cancel=false;let encoder;const samples=[];let description,error;for(const el of d.querySelectorAll('select,input,button'))el.disabled=true;$('animationCancel').disabled=false;$('animationCancel').hidden=false;try{if(!window.VideoEncoder)throw Error('Browser ini belum menyediakan encoder video. Gunakan Chrome atau Edge desktop terbaru.');draw(0);const config={codec:'avc1.64002a',width:canvas.width,height:canvas.height,bitrate:10000000,framerate:60,latencyMode:'realtime',avc:{format:'avc'}};const supported=await VideoEncoder.isConfigSupported(config);if(!supported.supported)throw Error('Encoder H.264 1080p/60 fps tidak tersedia pada browser ini.');encoder=new VideoEncoder({output:(chunk,meta)=>{const data=new Uint8Array(chunk.byteLength);chunk.copyTo(data);samples.push({data,key:chunk.type==='key'});if(meta.decoderConfig?.description)description=meta.decoderConfig.description;},error:e=>{error=e;}});encoder.configure(config);const count=duration()*60;for(let i=0;i<count;i++){if(cancel)throw Error('Ekspor dibatalkan.');if(error)throw error;draw(i/60);const frame=new VideoFrame(canvas,{timestamp:Math.round(i*1000000/60),duration:Math.round(1000000/60)});encoder.encode(frame,{keyFrame:i%120===0});frame.close();if(i%8===0){await encoder.flush();$('animationProgress').value=(i+1)/count;$('animationStatus').textContent='Merender '+(i+1)+' / '+count+' frame · 60 fps';await new Promise(r=>setTimeout(r,0));}}await encoder.flush();if(error)throw error;if(cancel)throw Error('Ekspor dibatalkan.');if(samples.length!==count)throw Error('Jumlah frame encoder tidak lengkap.');const blob=MP4Mux.build(samples,description,canvas.width,canvas.height,60),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=artwork.name+'-draw-on-'+duration()+'s.mp4';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);$('animationProgress').value=1;$('animationStatus').textContent='Selesai · '+canvas.width+' × '+canvas.height+' · 60 fps · '+duration()+' detik';elapsed=duration();draw(elapsed);}catch(e){$('animationStatus').textContent=e.message;}finally{if(encoder&&encoder.state!=='closed')encoder.close();exporting=false;for(const el of d.querySelectorAll('select,input,button'))el.disabled=false;$('animationCancel').hidden=true;}};
})();
